import { expect, test } from "bun:test";

const PACKAGE = `${import.meta.dir}/..`;

// `src/core/presets.ts` is generated from the ECMA-376 preset XML through the
// worker's own geometry encoder. When the encoder changes without a
// regeneration, the shipped table silently stops matching custom geometry.
// (`core/chart/metrics-data.ts` is generated by `tools/chart-oracle/gen_metrics.py`
// from Windows font files and Python; it cannot run here, see the evidence gap in
// docs/ARCHITECTURE.md § Gaps, limits and fidelity gaps.)
test("src/core/presets.ts is what scripts/compile-presets.ts produces from the shipped XML", async () => {
  const run = Bun.spawn(["bun", "scripts/compile-presets.ts", "--check", "scripts/presetShapeDefinitions.xml"], {
    cwd: PACKAGE,
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, code] = await Promise.all([new Response(run.stdout).text(), run.exited]);
  expect(stdout).toContain("presets match");
  expect(code).toBe(0);
}, 60_000);
